CREATE OR REPLACE FUNCTION public.top5_staff_of_month(_year integer,_month integer) RETURNS TABLE(staff_profile_id uuid,staff_name text,avg_score numeric,appraisal_count integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.staff_profile_id,p.last_name||', '||p.first_name,ROUND(AVG(a.average_score)::numeric,2),COUNT(*)::integer FROM public.staff_appraisals a JOIN public.profiles p ON p.id=a.staff_profile_id WHERE a.workflow_state IN ('approved','acknowledged') AND a.period_year=_year AND a.period_month=_month AND public.appraisal_can_view_profile(auth.uid(),p.id) GROUP BY a.staff_profile_id,p.last_name,p.first_name ORDER BY 3 DESC,4 DESC LIMIT 5 $$;
CREATE OR REPLACE FUNCTION public.top5_staff_of_year(_year integer) RETURNS TABLE(staff_profile_id uuid,staff_name text,avg_score numeric,appraisal_count integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.staff_profile_id,p.last_name||', '||p.first_name,ROUND(AVG(a.average_score)::numeric,2),COUNT(*)::integer FROM public.staff_appraisals a JOIN public.profiles p ON p.id=a.staff_profile_id WHERE a.workflow_state IN ('approved','acknowledged') AND a.period_year=_year AND public.appraisal_can_view_profile(auth.uid(),p.id) GROUP BY a.staff_profile_id,p.last_name,p.first_name ORDER BY 3 DESC,4 DESC LIMIT 5 $$;
REVOKE ALL ON FUNCTION public.top5_staff_of_month(integer,integer),public.top5_staff_of_year(integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.top5_staff_of_month(integer,integer),public.top5_staff_of_year(integer) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.appraisal_coverage_report(_period_year integer,_period_month integer DEFAULT NULL) RETURNS TABLE(staff_profile_id uuid,staff_id text,first_name text,last_name text,rank_name text,rank_level integer,department_name text,unit text,has_appraisal boolean,appraisal_status text,total_score numeric,duplicate_attempts integer,last_attempt_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_appraisals(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF; RETURN QUERY SELECT p.id,p.staff_id,p.first_name,p.last_name,r.name,r.level,d.name,p.unit,a.id IS NOT NULL,a.workflow_state,a.total_score,COALESCE(dup.cnt,0)::integer,dup.last_at FROM public.profiles p LEFT JOIN public.ranks r ON r.id=p.rank_id LEFT JOIN public.departments d ON d.id=p.department_id LEFT JOIN public.staff_appraisals a ON a.staff_profile_id=p.id AND a.period_year=_period_year AND COALESCE(a.period_month,0)=COALESCE(_period_month,0) LEFT JOIN (SELECT au.staff_profile_id,COUNT(*) cnt,MAX(au.created_at) last_at FROM public.staff_appraisal_audit au WHERE au.action='duplicate_attempt' AND au.period_year=_period_year AND COALESCE(au.period_month,0)=COALESCE(_period_month,0) GROUP BY au.staff_profile_id) dup ON dup.staff_profile_id=p.id WHERE p.status='active' AND public.appraisal_can_manage_profile(auth.uid(),p.id) ORDER BY r.level DESC NULLS LAST,p.last_name,p.first_name; END $$;
REVOKE ALL ON FUNCTION public.appraisal_coverage_report(integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.appraisal_coverage_report(integer,integer) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.appraisal_scores_server_only() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN RAISE EXCEPTION 'Use the authorized appraisal workflow'; END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER appraisal_header_server_only BEFORE INSERT OR UPDATE OR DELETE ON public.staff_appraisals FOR EACH ROW EXECUTE FUNCTION public.appraisal_scores_server_only();
CREATE TRIGGER appraisal_scores_server_only BEFORE INSERT OR UPDATE OR DELETE ON public.staff_appraisal_scores FOR EACH ROW EXECUTE FUNCTION public.appraisal_scores_server_only();